13		storepb "github.com/usememos/memos/proto/gen/store"
14		"github.com/usememos/memos/store"
15	)
16	
17	func (d *DB) CreateAttachment(ctx context.Context, create *store.Attachment) (*store.Attachment, error) {
18		fields := []string{"`uid`", "`filename`", "`blob`", "`type`", "`size`", "`creator_id`", "`memo_id`", "`storage_type`", "`reference`", "`payload`"}
19		placeholder := []string{"?", "?", "?", "?", "?", "?", "?", "?", "?", "?"}
20		storageType := ""
21		if create.StorageType != storepb.AttachmentStorageType_ATTACHMENT_STORAGE_TYPE_UNSPECIFIED {
22			storageType = create.StorageType.String()
23		}
24		payloadString := "{}"
25		if create.Payload != nil {
26			bytes, err := protojson.Marshal(create.Payload)
27			if err != nil {
28				return nil, errors.Wrap(err, "failed to marshal attachment payload")
29			}
30			payloadString = string(bytes)
31		}
32		args := []any{create.UID, create.Filename, create.Blob, create.Type, create.Size, create.CreatorID, create.MemoID, storageType, create.Reference, payloadString}
33	
34		stmt := "INSERT INTO `attachment` (" + strings.Join(fields, ", ") + ") VALUES (" + strings.Join(placeholder, ", ") + ")"
35		result, err := d.db.ExecContext(ctx, stmt, args...)
36		if err != nil {
37			return nil, err
38		}
39	
40		id, err := result.LastInsertId()
41		if err != nil {
42			return nil, err
43		}
44	
45		id32 := int32(id)
46		return d.GetAttachment(ctx, &store.FindAttachment{ID: &id32})
47	}
48	
49	func (d *DB) ListAttachments(ctx context.Context, find *store.FindAttachment) ([]*store.Attachment, error) {
50		where, args := []string{"1 = 1"}, []any{}
51	
52		if v := find.ID; v != nil {
53			where, args = append(where, "`attachment`.`id` = ?"), append(args, *v)
54		}
55		if v := find.UID; v != nil {
56			where, args = append(where, "`attachment`.`uid` = ?"), append(args, *v)
57		}
58		if v := find.CreatorID; v != nil {
59			where, args = append(where, "`attachment`.`creator_id` = ?"), append(args, *v)
60		}
61		if v := find.Filename; v != nil {
62			where, args = append(where, "`attachment`.`filename` = ?"), append(args, *v)
63		}
64		if v := find.FilenameSearch; v != nil {
65			where, args = append(where, "`attachment`.`filename` LIKE ?"), append(args, "%"+*v+"%")
66		}
67		if v := find.MemoID; v != nil {
68			where, args = append(where, "`attachment`.`memo_id` = ?"), append(args, *v)
69		}
70		if len(find.MemoIDList) > 0 {
71			placeholders := make([]string, 0, len(find.MemoIDList))
72			for range find.MemoIDList {
73				placeholders = append(placeholders, "?")
74			}
75			where = append(where, "`attachment`.`memo_id` IN ("+strings.Join(placeholders, ",")+")")
76			for _, id := range find.MemoIDList {
77				args = append(args, id)
78			}
79		}
80		if find.HasRelatedMemo {
81			where = append(where, "`attachment`.`memo_id` IS NOT NULL")
82		}
83		if find.StorageType != nil {
84			where, args = append(where, "`attachment`.`storage_type` = ?"), append(args, find.StorageType.String())
85		}
86	
87		if len(find.Filters) > 0 {
88			engine, err := filter.DefaultAttachmentEngine()
89			if err != nil {
90				return nil, errors.Wrap(err, "failed to get filter engine")
91			}
92			if err := filter.AppendConditions(ctx, engine, find.Filters, filter.DialectMySQL, &where, &args); err != nil {
93				return nil, errors.Wrap(err, "failed to append filter conditions")
94			}
95		}
96	
97		fields := []string{
98			"`attachment`.`id` AS `id`",
99			"`attachment`.`uid` AS `uid`",
100			"`attachment`.`filename` AS `filename`",
101			"`attachment`.`type` AS `type`",
102			"`attachment`.`size` AS `size`",
103			"`attachment`.`creator_id` AS `creator_id`",
104			"UNIX_TIMESTAMP(`attachment`.`created_ts`) AS `created_ts`",
105			"UNIX_TIMESTAMP(`attachment`.`updated_ts`) AS `updated_ts`",
106			"`attachment`.`memo_id` AS `memo_id`",
107			"`attachment`.`storage_type` AS `storage_type`",
108			"`attachment`.`reference` AS `reference`",
109			"`attachment`.`payload` AS `payload`",
110			"CASE WHEN `memo`.`uid` IS NOT NULL THEN `memo`.`uid` ELSE NULL END AS `memo_uid`",
111		}
112		if find.GetBlob {
113			fields = append(fields, "`attachment`.`blob` AS `blob`")
114		}
115	
116		query := "SELECT " + strings.Join(fields, ", ") + " FROM `attachment`" + " " +
117			"LEFT JOIN `memo` ON `attachment`.`memo_id` = `memo`.`id`" + " " +
118			"WHERE " + strings.Join(where, " AND ") + " " +
119			"ORDER BY `updated_ts` DESC"
120		if find.Limit != nil {
121			query = fmt.Sprintf("%s LIMIT %d", query, *find.Limit)
122			if find.Offset != nil {
123				query = fmt.Sprintf("%s OFFSET %d", query, *find.Offset)
124			}
125		}
126	
127		rows, err := d.db.QueryContext(ctx, query, args...)
128		if err != nil {
129			return nil, err
130		}
131		defer rows.Close()
132	
133		list := make([]*store.Attachment, 0)
134		for rows.Next() {
135			attachment := store.Attachment{}
136			var memoID sql.NullInt32
137			var storageType string
138			var payloadBytes []byte
139			dests := []any{
140				&attachment.ID,
141				&attachment.UID,
142				&attachment.Filename,
143				&attachment.Type,
144				&attachment.Size,
145				&attachment.CreatorID,
146				&attachment.CreatedTs,
147				&attachment.UpdatedTs,
148				&memoID,
149				&storageType,
150				&attachment.Reference,
151				&payloadBytes,
152				&attachment.MemoUID,
153			}
154			if find.GetBlob {
155				dests = append(dests, &attachment.Blob)
156			}
157			if err := rows.Scan(dests...); err != nil {
158				return nil, err
159			}
160	
161			if memoID.Valid {
162				attachment.MemoID = &memoID.Int32
163			}
164			attachment.StorageType = storepb.AttachmentStorageType(storepb.AttachmentStorageType_value[storageType])
165			payload := &storepb.AttachmentPayload{}
166			if err := protojsonUnmarshaler.Unmarshal(payloadBytes, payload); err != nil {
167				return nil, err
168			}
169			attachment.Payload = payload
170			list = append(list, &attachment)
171		}
172	
173		if err := rows.Err(); err != nil {
174			return nil, err
175		}
176	
177		return list, nil
178	}
179	
180	func (d *DB) GetAttachment(ctx context.Context, find *store.FindAttachment) (*store.Attachment, error) {
181		list, err := d.ListAttachments(ctx, find)
182		if err != nil {
183			return nil, err
184		}
185		if len(list) == 0 {
186			return nil, nil
187		}
188	
189		return list[0], nil
