192	func (d *DB) UpdateAttachment(ctx context.Context, update *store.UpdateAttachment) error {
193		set, args := []string{}, []any{}
194	
195		if v := update.UID; v != nil {
196			set, args = append(set, "`uid` = ?"), append(args, *v)
197		}
198		if v := update.UpdatedTs; v != nil {
199			set, args = append(set, "`updated_ts` = FROM_UNIXTIME(?)"), append(args, *v)
